  /**
   * @method
   * @name bit2c#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://bit2c.co.il/home/api#transactions
   * @see https://bit2c.co.il/home/api#trades
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any optionValue = this->safeString(
                     this->options,
                     std::string(
                         "fetchTradesMethod")); // kept here for backward
                                                // compatibility #29154
                 std::any method = this->handleOption(
                     std::string("fetchTrades"), std::string("method"),
                     optionValue); // public_get_exchanges_pair_trades or
                                   // public_get_exchanges_pair_lasttrades
                 std::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("date"),
                              this->parseToInt(since));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // max 100000
                 }
                 std::any responseList = ccxt::list{};
                 if (isTrue(isEqual(
                         method,
                         std::string("public_get_exchanges_pair_trades")))) {
                   std::any response =
                       awaitValue(this->publicGetExchangesPairTrades(
                           this->extend(request, params)));
                   //
                   //     [
                   //         {"date":1651785980,"price":127975.68,"amount":0.3750321,"isBid":true,"tid":1261018},
                   //         {"date":1651785980,"price":127987.70,"amount":0.0389527820303982335802581029,"isBid":true,"tid":1261020},
                   //         {"date":1651786701,"price":128084.03,"amount":0.0015614749161156156626239821,"isBid":true,"tid":1261022},
                   //     ]
                   //
                   if (isTrue(isString(response))) {
                     throw ExchangeError(toString(response));
                   }
                   responseList = this->toArray(response);
                 } else {
                   std::any response =
                       awaitValue(this->publicGetExchangesPairLasttrades(
                           this->extend(request, params)));
                   if (isTrue(isString(response))) {
                     throw ExchangeError(toString(response));
                   }
                   responseList = this->toArray(response);
                 }
                 return this->parseTrades(responseList, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bit2c#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://bit2c.co.il/home/api#balance
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<std::any>
  fetchTradingFees(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any response =
                     awaitValue(this->privateGetAccountBalance(params));
                 //
                 //     {
                 //         "AVAILABLE_NIS": 0.0,
                 //         "NIS": 0.0,
                 //         "LOCKED_NIS": 0.0,
                 //         "AVAILABLE_BTC": 0.0,
                 //         "BTC": 0.0,
                 //         "LOCKED_BTC": 0.0,
                 //         ...
                 //         "Fees": {
                 //             "BtcNis": { "FeeMaker": 1.0, "FeeTaker": 1.0 },
                 //             "EthNis": { "FeeMaker": 1.0, "FeeTaker": 1.0 },
                 //             ...
                 //         }
                 //     }
                 //
                 std::any fees = this->safeValue(response, std::string("Fees"),
                                                 ccxt::dict{});
                 std::any keys = getObjectKeys(fees);
                 std::any result = ccxt::dict{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(keys));
                      postFixIncrement(i)) {
                   std::any marketId = ::getValue(keys, i);
                   std::any symbol = this->safeSymbol(marketId);
                   std::any fee = this->safeValue(fees, marketId);
                   std::any makerString =
                       this->safeString(fee, std::string("FeeMaker"));
                   std::any takerString =
                       this->safeString(fee, std::string("FeeTaker"));
                   std::any maker = this->parseNumber(ccxt::Precise::stringDiv(
                       makerString, std::string("100")));
                   std::any taker = this->parseNumber(ccxt::Precise::stringDiv(
                       takerString, std::string("100")));
                   ::setValue(result, symbol,
                              ccxt::dict{
                                  {std::string("info"), fee},
                                  {std::string("symbol"), symbol},
                                  {std::string("taker"), taker},
                                  {std::string("maker"), maker},
                                  {std::string("percentage"), true},
                                  {std::string("tierBased"), true},
                              });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name bit2c#createOrder
   * @description create a trade order
   * @see https://bit2c.co.il/home/api#addo
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("Amount"), amount},
                            {std::string("Pair"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any response = std::any{};
                        if (isTrue(isEqual(type, std::string("market")))) {
                          if (isTrue(isEqual(side, std::string("buy")))) {
                            response = awaitValue(
                                this->privatePostOrderAddOrderMarketPriceBuy(
                                    this->extend(request, params)));
                          } else {
                            response = awaitValue(
                                this->privatePostOrderAddOrderMarketPriceSell(
                                    this->extend(request, params)));
                          }
                        } else {
                          ::setValue(request, std::string("Price"), price);
                          std::any amountString = this->numberToString(amount);
                          std::any priceString = this->numberToString(price);
                          ::setValue(
                              request, std::string("Total"),
                              this->parseToNumeric(ccxt::Precise::stringMul(
                                  amountString, priceString)));
                          ::setValue(request, std::string("IsBid"),
                                     (isEqual(side, std::string("buy"))));
                          response = awaitValue(this->privatePostOrderAddOrder(
                              this->extend(request, params)));
                        }
                        return this->parseOrder(response, market);
                      })
        .share();
  }

